INSERT INTO "materiales" ("id", "titulo", "autores", "descripcion", "tipo", "tema", "publico", "fecha", "formato", "paginas", "portada", "url", "fuente", "doi", "cita", "destacado", "rotulo", "frase", "detalle", "publicado", "publicado_en", "creado_en") VALUES
  ('a542f6bd-c0b5-4184-9cfc-caa2ea9be1fc', 'Taller de conceptos básicos del Sistema Solar adaptado a grupos de nivel primaria y secundaria', NULL, 'Diseño y evaluación de un taller semanal sobre el Sistema Solar para chicas y chicos de 8 a 13 años: historietas, modelos de cuerpos celestes con materiales de bajo costo y juegos de mesa para formular preguntas, leer, reflexionar y manipular. En más del 90 % de las sesiones, más de la mitad del grupo alcanzó los aprendizajes esperados.', 'Artículos', 'Divulgación científica', 'Docentes', '2026-01', 'PDF', 14, '{"src":"/biblioteca/portadas/16-taller-sistema-solar.webp","alt":"Portada de «Taller de conceptos básicos del Sistema Solar adaptado a grupos de nivel primaria y secundaria»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://rmf.smf.mx/ojs/index.php/rmf-e/article/view/8047', 'Revista Mexicana de Física E', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '0 milliseconds'),
  ('58e0888f-db77-424f-a4f8-589bd791c114', 'Formación y desarrollo profesional de profesores de matemáticas: implementación de las investigaciones en Educación Matemática', 'Judith Alejandra Hernández Sánchez, David Alfonso Páez y Lilia Patricia Aké Tec (editores)', 'Libro editado por tres especialistas en formación docente, entre ellas Judith Hernández, del equipo de ED, sobre cómo llevar las investigaciones en Educación Matemática a la formación inicial y continua del profesorado de matemáticas.', 'Libros', 'Desarrollo profesional docente', 'Formadoras y formadores', '2026', 'PDF', 132, '{"src":"/biblioteca/portadas/10-formacion-desarrollo-profesional-somidem.webp","alt":"Portada de «Formación y desarrollo profesional de profesores de matemáticas: implementación de las investigaciones en Educación Matemática»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://editorialsomidem.org.mx/', 'Editorial SOMIDEM', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '1 milliseconds'),
  ('56a35a9a-bfff-47b8-9bfc-c4c62f6669f5', 'Problemas de probabilidad de primero de secundaria resueltos mediante el uso de calculadora para medir el razonamiento estadístico', NULL, 'Problemas de probabilidad para primer año de secundaria, resueltos con calculadora, como instrumento para medir el razonamiento estadístico del estudiantado. Capítulo del libro de jóvenes investigadoras e investigadores de SOMIDEM.', 'Capítulos de libro', 'Estadística y probabilidad', 'Docentes', '2026', 'PDF', 19, '{"src":"/biblioteca/portadas/09-probabilidad-calculadora-somidem.webp","alt":"Portada de «Problemas de probabilidad de primero de secundaria resueltos mediante el uso de calculadora para medir el razonamiento estadístico»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/SOMIDEM/S3/2026/01-05', 'SOMIDEM', '10.24844/somidem/s3/2026/01-05', 'Rodríguez González, B. A., Briceño Solís, E. C. y Hernández Sánchez, J. A. (2026). Problemas de probabilidad de primero de secundaria resueltos mediante el uso de calculadora para medir el razonamiento estadístico. Voces emergentes de jóvenes en la investigación en educación matemática. https://doi.org/10.24844/somidem/s3/2026/01-05', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '2 milliseconds'),
  ('98f2912d-998e-439e-b547-47a723391b00', 'Estudios histórico-epistemológicos en matemática educativa: tendencias metodológicas en Latinoamérica', NULL, 'Describe las tendencias metodológicas de los estudios histórico-epistemológicos hechos desde instituciones latinoamericanas, con un análisis bibliométrico y un análisis de contenido de artículos de revistas de Matemática Educativa publicados entre 2017 y 2022.', 'Artículos', 'Historia y epistemología', 'Investigadoras e investigadores', '2026', 'PDF', NULL, '{"src":"/biblioteca/portadas/29-estudios-historico-epistemologicos-matematica.webp","alt":"Portada de «Estudios histórico-epistemológicos en matemática educativa: tendencias metodológicas en Latinoamérica»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.15517/sd9nf605', 'Cuadernos de Investigación y Formación en Educación Matemática', '10.15517/sd9nf605', 'Romero Fonseca, F. y López Acosta, L. A. (2026). Estudios histórico-epistemológicos en matemática educativa: tendencias metodológicas en Latinoamérica. Cuadernos de Investigación y Formación en Educación Matemática, 19(1), 121–149. https://doi.org/10.15517/sd9nf605', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '3 milliseconds'),
  ('1627aac7-cb15-4d5f-a1f7-3498b7a5da4d', 'La formación ciudadana en las prácticas educativas con las matemáticas', NULL, 'Artículo de reflexión sobre la relación entre educación matemática y ciudadanía, nacido de un proyecto de la Universidad Pedagógica Nacional de Colombia: subjetividad, creatividad y ética como categorías que configuran las prácticas educativas con las matemáticas y forman un ciudadano particular.', 'Artículos', 'Ciudadanía y justicia social', 'Docentes', '2026-07', 'PDF', NULL, '{"src":"/biblioteca/portadas/32-formacion-ciudadana-practicas-educativas.webp","alt":"Portada de «La formación ciudadana en las prácticas educativas con las matemáticas»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.17227/pys.num65-22606', 'Pedagogía y Saberes', '10.17227/pys.num65-22606', 'Torres-Puentes, E., Salazar-Amaya, C. y Balda Álvarez, P. A. (2026). La formación ciudadana en las prácticas educativas con las matemáticas. Pedagogía y Saberes, 177–188. https://doi.org/10.17227/pys.num65-22606', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '4 milliseconds'),
  ('3e3eb811-75b3-4c9d-a18b-a4841b7530de', 'Contextos de significación en la explicación de la construcción del conocimiento matemático', NULL, 'Presenta dos contextos de significación para la matemática escolar, la huerta escolar y una comunidad universitaria de ingeniería, y analiza cómo la razón matemática y las gráficas cartesianas se resignifican según cómo se usan en cada uno: la siembra y el riego en un caso, las tareas de la ingeniería en el otro.', 'Artículos', 'Pensamiento proporcional', 'Investigadoras e investigadores', '2026-01', 'PDF', 19, '{"src":"/biblioteca/portadas/33-contextos-significacion-explicacion-construccion.webp","alt":"Portada de «Contextos de significación en la explicación de la construcción del conocimiento matemático»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.17227/ted.num59-22283', 'Tecné, Episteme y Didaxis', '10.17227/ted.num59-22283', 'Tuyub Sánchez, I., Balda Álvarez, P. A. y Buendía Abalos, G. (2026). Contextos de significación en la explicación de la construcción del conocimiento matemático. Tecné, Episteme y Didaxis: TED, 266–284. https://doi.org/10.17227/ted.num59-22283', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '5 milliseconds'),
  ('2aa3fbbe-0f3d-4af0-aaa3-591df1f8cc36', 'Un ejercicio de empoderamiento docente en un curso de formación posgradual', NULL, 'Resultados de un proceso de empoderamiento docente en un curso de posgrado para profesores de matemáticas, en ocho sesiones híbridas: describe cada momento del curso, el proceso vivido y cómo redundó en el rediseño del discurso matemático escolar.', 'Artículos', 'Desarrollo profesional docente', 'Formadoras y formadores', '2026', 'PDF', NULL, '{"src":"/biblioteca/portadas/34-ejercicio-empoderamiento-docente-curso.webp","alt":"Portada de «Un ejercicio de empoderamiento docente en un curso de formación posgradual»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.54541/reviem.v6i1.152', 'REVIEM', '10.54541/reviem.v6i1.152', 'Balda Álvarez, P. A. y Bohórquez Arenas, L. Á. (2026). Un ejercicio de empoderamiento docente en un curso de formación posgradual. Revista Venezolana de Investigación en Educación Matemática, 6(1), 1–26. https://doi.org/10.54541/reviem.v6i1.152', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '6 milliseconds'),
  ('a66f3d0a-2dc4-40bb-a7b3-1d090737ccf2', 'Resolución de problemas en el marco de los círculos matemáticos. Una experiencia con estudiantes de Argentina y Colombia', NULL, 'Describe la experiencia de dos grupos de estudiantes, uno en Colombia y otro en Argentina, resolviendo problemas con la metodología de los círculos matemáticos. Un estudio de casos con registros en video que identifica racionalidades contextualizadas en las estrategias, enriquecidas por el diálogo entre pares.', 'Artículos', 'Resolución de problemas', 'Docentes', '2026-02', 'PDF', NULL, '{"src":"/biblioteca/portadas/35-resolucion-problemas-marco-circulos.webp","alt":"Portada de «Resolución de problemas en el marco de los círculos matemáticos. Una experiencia con estudiantes de Argentina y Colombia»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://scpmluisbalbuena.org/publicacion-numeros/articulo-3-122/', 'Números', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '7 milliseconds'),
  ('77e33cff-b8a7-4e00-a434-520435e54a7d', 'Articulación del pensamiento y lenguaje variacional en una situación de aprendizaje para la enseñanza de la derivada', NULL, 'Una situación de aprendizaje para la comprensión conceptual de la derivada en secundaria a partir del enfriamiento de silicona: identificar magnitudes, establecer referencias, analizar registros y aproximarse a la variación instantánea, articulando los estadios del Pensamiento y Lenguaje Variacional con las fases de diseño de situaciones.', 'Artículos', 'Pensamiento variacional', 'Docentes', '2026', 'PDF', NULL, '{"src":"/biblioteca/portadas/41-articulacion-pensamiento-lenguaje-variacional.webp","alt":"Portada de «Articulación del pensamiento y lenguaje variacional en una situación de aprendizaje para la enseñanza de la derivada»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.46618/iime.271', 'IIME', '10.46618/iime.271', 'Espinoza-Salomón, A., Jorquera-Soto, R., Osorio-Gómez, T. y Pérez Vera, I. E. (2026). Articulación del pensamiento y lenguaje variacional en una situación de aprendizaje para la enseñanza de la derivada. Investigación e Innovación en Matemática Educativa, 11, 1–26. https://doi.org/10.46618/iime.271', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '8 milliseconds'),
  ('ac49f77f-d035-4a6c-993f-a6bdfecb431a', 'Análisis de estrategias de resolución en una experiencia de modelación matemática escolar sobre consumo y producción sostenibles', NULL, 'Analiza las estrategias de resolución de estudiantes en una experiencia de modelación matemática sobre consumo y producción sostenibles: cómo movilizan sus saberes para cuestionar el impacto ambiental de la industria del fast fashion, articulando la matemática con problemáticas sociales cercanas a su realidad.', 'Artículos', 'Tecnología y modelación', 'Docentes', '2026', 'PDF', NULL, '{"src":"/biblioteca/portadas/42-analisis-estrategias-resolucion-experiencia.webp","alt":"Portada de «Análisis de estrategias de resolución en una experiencia de modelación matemática escolar sobre consumo y producción sostenibles»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.15517/v6w6x527', 'Cuadernos de Investigación y Formación en Educación Matemática', '10.15517/v6w6x527', 'Giovanetti, S., Riquelme, S., Vilches, R. y Pérez Vera, I. E. (2026). Análisis de estrategias de resolución en una experiencia de modelación matemática escolar sobre consumo y producción sostenibles. Cuadernos de Investigación y Formación en Educación Matemática, 19(1), 179–202. https://doi.org/10.15517/v6w6x527', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '9 milliseconds'),
  ('e2001c90-35a7-4020-a879-ca504c378ab9', 'Modelación matemática escolar de la elipse en contexto astronómico', NULL, 'Diseño e implementación de una situación de aprendizaje para enseñar la elipse desde las leyes de Kepler: cómo construyen significados los estudiantes al vincularla con el movimiento planetario, en un estudio de casos con la modelación entendida como práctica social.', 'Artículos', 'Tecnología y modelación', 'Docentes', '2026', 'PDF', NULL, '{"src":"/biblioteca/portadas/43-modelacion-matematica-escolar-elipse.webp","alt":"Portada de «Modelación matemática escolar de la elipse en contexto astronómico»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.46219/rechiem.v18i1.212', 'RECHIEM', '10.46219/rechiem.v18i1.212', 'Pacheco López, K. y Pérez Vera, I. E. (2026). Modelación matemática escolar de la elipse en contexto astronómico. Revista Chilena de Educación Matemática, 18(1), 55–72. https://doi.org/10.46219/rechiem.v18i1.212', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '10 milliseconds'),
  ('c189d22b-472c-47e4-9fd1-c109cf64a529', 'Resignificación del conocimiento matemático escolar en un espacio de desarrollo profesional docente', NULL, 'Analiza cómo se resignifica el conocimiento matemático escolar en docentes en servicio durante un programa de desarrollo profesional orientado al empoderamiento docente, con dos episodios de pensamiento algebraico y geométrico. La resignificación aparece como un proceso cíclico, colectivo y progresivo, parte constitutiva de la profesión docente en matemáticas.', 'Artículos', 'Desarrollo profesional docente', 'Investigadoras e investigadores', '2025-12', 'PDF', 39, '{"src":"/biblioteca/portadas/02-resignificacion-cme-relime.webp","alt":"Portada de «Resignificación del conocimiento matemático escolar en un espacio de desarrollo profesional docente»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.12802/relime.2025.28.e805', 'RELIME', '10.12802/relime.2025.28.e805', 'Reyes-Gasperini, D. y Gómez Osalde, K. (2025). Resignificación del conocimiento matemático escolar en un espacio de desarrollo profesional docente. Revista Latinoamericana de Investigación en Matemática Educativa, 28. https://doi.org/10.12802/relime.2025.28.e805', 1, 'RELIME 2025', 'La resignificación como parte de la profesión docente.', 'Las dos autoras firman con filiación Empoderamiento Docente: es la investigación más reciente del equipo y muestra, con episodios de aula, cómo se configura el cambio de relación con la matemática escolar dentro de un programa de desarrollo profesional.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '11 milliseconds'),
  ('a534cec7-b623-40da-8f4d-123f55a8ec8f', 'Una aproximación variacional para la significación de los criterios de la derivada', NULL, 'Una aproximación variacional para darle significado a los criterios de la derivada más allá de su aplicación algorítmica: situaciones donde el cambio y la variación son el objeto de estudio y lo que se estudia es cómo varía una cantidad, no solo qué regla aplicar.', 'Artículos', 'Pensamiento variacional', 'Investigadoras e investigadores', '2025-05', 'PDF', 24, '{"src":"/biblioteca/portadas/14-criterios-derivada-variacional.webp","alt":"Portada de «Una aproximación variacional para la significación de los criterios de la derivada»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.35763/aiem27.6157', 'AIEM', '10.35763/aiem27.6157', 'Zaldívar Rojas, J. D., Cabrera Chim, L. M. y Jiménez Villalpando, A. V. (2025). Una aproximación variacional para la significación de los criterios de la derivada. Avances de Investigación en Educación Matemática, 157–177. https://doi.org/10.35763/aiem27.6157', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '12 milliseconds'),
  ('e30234d2-0ae3-437e-915c-3d78d4f1b806', 'Referentes teóricos para el diseño de situaciones variacionales', NULL, 'Qué principios sostienen el diseño de situaciones variacionales: tareas donde el cambio y la variación son lo que se estudia. Capítulo del libro del taller Tendencias en la Educación Matemática Basada en la Investigación (BUAP), editado por SOMIDEM.', 'Capítulos de libro', 'Pensamiento variacional', 'Formadoras y formadores', '2025', 'PDF', 30, '{"src":"/biblioteca/portadas/15-situaciones-variacionales-somidem.webp","alt":"Portada de «Referentes teóricos para el diseño de situaciones variacionales»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://editorialsomidem.org.mx/?view=viewpub&id=1048', 'Editorial SOMIDEM', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '13 milliseconds'),
  ('a56bfdd2-140c-44e8-9de8-247f1afba808', 'Problematizar la matemática escolar: ¿cómo contribuye al desarrollo profesional docente?', NULL, 'Argumenta cómo la problematización de la matemática escolar contribuye al desarrollo profesional docente: un proceso de reflexión que produce confrontaciones, resignificaciones y un cambio de relación con el conocimiento. Analiza dos episodios con el modelo reflexivo de la matemática escolar.', 'Artículos', 'Desarrollo profesional docente', 'Formadoras y formadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/19-problematizar-matematica-escolar-contribuye.webp","alt":"Portada de «Problematizar la matemática escolar: ¿cómo contribuye al desarrollo profesional docente?»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.1590/1980-4415v39a230249', 'Bolema', '10.1590/1980-4415v39a230249', 'Báez Melendres, M., Flores-García, R. y Reyes-Gasperini, D. (2025). Problematizar la matemática escolar: ¿cómo contribuye al desarrollo profesional docente? Bolema: Boletim de Educação Matemática, 39. https://doi.org/10.1590/1980-4415v39a230249', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '14 milliseconds'),
  ('27b83406-3c00-4564-a07b-e615a5131a53', 'La Geometría Analítica y su Transposición Didáctica Externa. Algunos ejemplos de México y Costa Rica', NULL, 'Caracteriza la transposición didáctica externa que sufrió la geometría analítica en la escuela, comparando un estudio histórico-epistemológico sobre la emergencia de las ecuaciones con parámetros y variables con lo que dicen los programas de estudio y los libros de texto de México y Costa Rica.', 'Artículos', 'Geometría', 'Investigadoras e investigadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/30-geometria-analitica-transposicion-didactica.webp","alt":"Portada de «La Geometría Analítica y su Transposición Didáctica Externa. Algunos ejemplos de México y Costa Rica»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.54541/reviem.v5i1.129', 'REVIEM', '10.54541/reviem.v5i1.129', 'López Acosta, L. A. (2025). La Geometría Analítica y su Transposición Didáctica Externa. Algunos ejemplos de México y Costa Rica. Revista Venezolana de Investigación en Educación Matemática, 5(1), 1–29. https://doi.org/10.54541/reviem.v5i1.129', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '15 milliseconds'),
  ('cefca2b6-b4dd-4272-8098-6188f1468023', '¿Es posible formar ciudadanos críticos en las aulas colombianas de matemáticas?', NULL, 'Analiza tres documentos curriculares del Ministerio de Educación de Colombia para mostrar qué potencial ofrecen, en propósitos, contenidos y metodologías, para formar ciudadanos críticos desde las aulas de matemáticas, según los planteamientos de la educación matemática crítica.', 'Artículos', 'Ciudadanía y justicia social', 'Docentes', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/36-es-posible-formar-ciudadanos.webp","alt":"Portada de «¿Es posible formar ciudadanos críticos en las aulas colombianas de matemáticas?»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.54104/papeles.v17n34.2156', 'Revista Papeles', '10.54104/papeles.v17n34.2156', 'Sánchez Naranjo, Y. P. y Balda Álvarez, P. A. (2025). ¿Es posible formar ciudadanos críticos en las aulas colombianas de matemáticas? Papeles, 17(34). https://doi.org/10.54104/papeles.v17n34.2156', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '16 milliseconds'),
  ('36a39f24-e8ff-4e6c-8bdd-45aa296930d1', 'Resignificación colectiva de lo cuadrático en el estudio del plano inclinado', NULL, 'Explora los significados que emergen sobre lo cuadrático y la derivada en una modelación empírica del plano inclinado con futuros profesores de matemática: veinte informes grupales que muestran la diversidad de usos y concepciones sobre los parámetros del modelo cuadrático y sobre la derivada.', 'Artículos', 'Tecnología y modelación', 'Formadoras y formadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/44-resignificacion-colectiva-lo-cuadratico.webp","alt":"Portada de «Resignificación colectiva de lo cuadrático en el estudio del plano inclinado»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.61174/recacym.v21i2.235', 'El Cálculo y su Enseñanza', '10.61174/recacym.v21i2.235', 'Pérez Vera, I. E. (2025). Resignificación colectiva de lo cuadrático en el estudio del plano inclinado. El cálculo y su enseñanza, 21(2), 7–36. https://doi.org/10.61174/recacym.v21i2.235', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '17 milliseconds'),
  ('2665b2eb-909d-4ff8-88aa-89150f0c6b18', 'Integración de modelación matemática, inteligencia artificial generativa y situaciones de aprendizaje para la enseñanza del cálculo escolar', NULL, 'Una situación de aprendizaje para superar obstáculos en la enseñanza de la derivada en secundaria, basada en el plano inclinado de Galileo: combina el ciclo de modelación de Borromeo y las fases de situaciones de aprendizaje de Balda, con herramientas de inteligencia artificial generativa.', 'Artículos', 'Tecnología y modelación', 'Docentes', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/45-integracion-modelacion-matematica-inteligencia.webp","alt":"Portada de «Integración de modelación matemática, inteligencia artificial generativa y situaciones de aprendizaje para la enseñanza del cálculo escolar»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.15517/bh306f78', 'Cuadernos de Investigación y Formación en Educación Matemática', '10.15517/bh306f78', 'Saavedra Messina, S., Silva Riveros, A. y Pérez Vera, I. E. (2025). Integración de modelación matemática, inteligencia artificial generativa y situaciones de aprendizaje para la enseñanza del cálculo escolar. Cuadernos de Investigación y Formación en Educación Matemática, 18(2), 25–48. https://doi.org/10.15517/bh306f78', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '18 milliseconds'),
  ('4a740567-3276-47d8-bde3-6032b3fa25be', 'Modelación matemática en la formación inicial docente: una experiencia desde la perspectiva feminista', NULL, 'Examina la modelación matemática en la formación inicial docente desde una perspectiva feminista, con una situación sobre la variación de la temperatura corporal en el ciclo menstrual: las dinámicas de género que emergen en el proceso y la reflexión crítica sobre los conocimientos matemáticos.', 'Artículos', 'Ciudadanía y justicia social', 'Formadoras y formadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/46-modelacion-matematica-formacion-inicial.webp","alt":"Portada de «Modelación matemática en la formación inicial docente: una experiencia desde la perspectiva feminista»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.29035/ucmaule.69.115', 'UCMaule', '10.29035/ucmaule.69.115', 'Salazar-Cortez, P. y Pérez Vera, I. E. (2025). Modelación matemática en la formación inicial docente: una experiencia desde la perspectiva feminista. Revista UCMaule, 115–138. https://doi.org/10.29035/ucmaule.69.115', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '19 milliseconds'),
  ('60c483ce-a8e9-4801-9fa8-34050bec024f', 'Sesgos de género en Modelación Matemática Escolar: impacto en aprendizaje y autopercepción docente en formación', NULL, 'Estudio de caso sobre la experiencia de una profesora en formación en un curso de modelación matemática y tecnología, para identificar posibles sesgos de género: pese a un buen desempeño académico, enfrenta baja autoconfianza y poca participación.', 'Artículos', 'Ciudadanía y justicia social', 'Formadoras y formadores', '2025', 'PDF', 25, '{"src":"/biblioteca/portadas/47-sesgos-genero-modelacion-matematica.webp","alt":"Portada de «Sesgos de género en Modelación Matemática Escolar: impacto en aprendizaje y autopercepción docente en formación»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://revistas.umce.cl/index.php/RChEC/article/view/3001', 'Revista Chilena de Educación Científica', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '20 milliseconds'),
  ('03c5be67-b66e-4aae-a604-5a947920f25c', 'Significados de la razón geométrica en la colisión inelástica', NULL, 'Explora la construcción de significados sobre la progresión geométrica en la formación inicial docente mediante ciclos de modelación del fenómeno de la colisión inelástica, con cinco estudiantes de Pedagogía en Matemática de la UMCE que calcularon razones geométricas a partir de datos experimentales.', 'Artículos', 'Pensamiento proporcional', 'Formadoras y formadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/48-significados-razon-geometrica-colision.webp","alt":"Portada de «Significados de la razón geométrica en la colisión inelástica»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.5377/paradigma.v32i53.20560', 'Paradigma', '10.5377/paradigma.v32i53.20560', 'Salazar Cortez, P. y Pérez Vera, I. E. (2025). Significados de la razón geométrica en la colisión inelástica. Paradigma: Revista de Investigación Educativa, 32(53), 159–180. https://doi.org/10.5377/paradigma.v32i53.20560', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '21 milliseconds'),
  ('9940954b-d28d-4b5e-a6b2-1bc68b02e053', 'Decision-making in contexts of risk and uncertainty: An instrument for secondary education', NULL, 'Formulación y validación de contenido de un cuestionario de respuesta forzada para explorar cómo estudiantes de secundaria toman decisiones en contextos de riesgo e incertidumbre, a partir de seis situaciones cotidianas.', 'Artículos', 'Estadística y probabilidad', 'Investigadoras e investigadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/55-decision-making-contexts-risk.webp","alt":"Portada de «Decision-making in contexts of risk and uncertainty: An instrument for secondary education»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.29333/ejmste/17175', 'Eurasia Journal', '10.29333/ejmste/17175', 'Vergara-Gómez, A. y Henríquez-Rivas, C. A. (2025). Decision-making in contexts of risk and uncertainty: An instrument for secondary education. Eurasia Journal of Mathematics, Science and Technology Education, 21(10), em2717. https://doi.org/10.29333/ejmste/17175', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '22 milliseconds'),
  ('62003079-f286-4a34-bc53-a8ee4437b734', 'Pensamiento probabilístico o intuición en el dilema de Monty Hall', NULL, 'Adapta el problema de Monty Hall para jóvenes de enseñanza media, en el marco de la incorporación de la toma de decisiones al currículo chileno: un estudio de caso con dos estudiantes que mira la dimensión cognitiva de la probabilidad y la dimensión intuitivo-afectiva de sesgos y heurísticas.', 'Artículos', 'Estadística y probabilidad', 'Docentes', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/56-pensamiento-probabilistico-o-intuicion.webp","alt":"Portada de «Pensamiento probabilístico o intuición en el dilema de Monty Hall»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.33996/revistahorizontes.v9i40.1125', 'Horizontes', '10.33996/revistahorizontes.v9i40.1125', 'Fuentes Rodríguez, D. B., Guajardo Becerra, J. O. y Vergara-Gómez, A. (2025). Pensamiento probabilístico o intuición en el dilema de Monty Hall. Horizontes. Revista de Investigación en Ciencias de la Educación, 9(40), 36–50. https://doi.org/10.33996/revistahorizontes.v9i40.1125', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '23 milliseconds'),
  ('e9a0e2b3-dfa5-4a09-9c58-b1038e70e7df', '¿Juguemos CATAN? Explorando el desarrollo de los pensamientos probabilístico y estratégico', NULL, 'Caracteriza el pensamiento estratégico y el pensamiento probabilístico de estudiantes universitarios mientras toman decisiones jugando CATAN, en seis sesiones de juego con seis estudiantes de una universidad chilena.', 'Artículos', 'Estadística y probabilidad', 'Investigadoras e investigadores', '2025', 'PDF', NULL, '{"src":"/biblioteca/portadas/57-juguemos-catan-explorando-desarrollo.webp","alt":"Portada de «¿Juguemos CATAN? Explorando el desarrollo de los pensamientos probabilístico y estratégico»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.21703/rexe.v24i56.3302', 'REXE', '10.21703/rexe.v24i56.3302', 'Ganga-Cáceres, V., Pérez-Gajardo, E., Reyes-Astorga, M. y Vergara-Gómez, A. (2025). ¿Juguemos CATAN? Explorando el desarrollo de los pensamientos probabilístico y estratégico. Revista de Estudios y Experiencias en Educación, 24(56), 209–224. https://doi.org/10.21703/rexe.v24i56.3302', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '24 milliseconds'),
  ('0614b3bc-1dc7-410d-b98b-3a741c2bfb93', '¿Qué significados de la derivada favorece un profesor en su planeación de clase?', NULL, 'Análisis de contenido de las planeaciones de cuatro docentes sobre la enseñanza de la derivada: cómo articulan y organizan sus significados, y la distancia entre lo que propone el programa de estudios y lo que llega a la planeación, donde predomina lo algorítmico y simbólico.', 'Artículos', 'Pensamiento variacional', 'Docentes', '2024', 'PDF', 32, '{"src":"/biblioteca/portadas/13-significados-derivada-planeacion.webp","alt":"Portada de «¿Qué significados de la derivada favorece un profesor en su planeación de clase?»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.33010/ie_rie_rediech.v15i0.1975', 'IE REDIECH', '10.33010/ie_rie_rediech.v15i0.1975', 'Briceño Solís, E. C., Hernández Sánchez, J. A. y Morales de la Cruz, J. A. (2024). ¿Qué significados de la derivada favorece un profesor en su planeación de clase? IE Revista de Investigación Educativa de la REDIECH, 15, e1975. https://doi.org/10.33010/ie_rie_rediech.v15i0.1975', 4, 'La derivada', 'Qué se planifica y qué dice el programa.', 'Dos integrantes del equipo analizan planeaciones reales de clase sobre la derivada y muestran la distancia entre los significados del programa de estudios y los que llegan al aula.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '25 milliseconds'),
  ('a54c7956-793c-4cfe-ba28-1299a84cd36f', 'Implementación del manual «Álgebra dinámica» y el software GeoGebra como recurso didáctico para el aprendizaje de álgebra elemental en el nivel medio superior', NULL, 'Cómo se implementó el manual «Álgebra dinámica» con GeoGebra como recurso para aprender álgebra elemental en el nivel medio superior. Capítulo del libro Intervenciones educativas para la incidencia social (UASLP).', 'Capítulos de libro', 'Tecnología y modelación', 'Docentes', '2024', 'PDF', 48, '{"src":"/biblioteca/portadas/08-algebra-dinamica-geogebra.webp","alt":"Portada de «Implementación del manual «Álgebra dinámica» y el software GeoGebra como recurso didáctico para el aprendizaje de álgebra elemental en el nivel medio superior»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.researchgate.net/publication/389785466_INTERVENCIONES_EDUCATIVAS_PARA_LA_INCIDENCIA_SOCIAL', 'ResearchGate', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '26 milliseconds'),
  ('a0623e3f-213c-424f-9fe7-4984122b3b57', 'Rúbrica para evaluar el desarrollo del pensamiento y lenguaje variacional', NULL, 'Presenta un esquema y una rúbrica analítica para promover y evaluar el desarrollo del pensamiento y lenguaje variacional, sintetizados a partir de lo reportado por esa línea de investigación. La rúbrica fue validada por expertos; sigue probarla en aulas de distintos niveles y ante distintas situaciones variacionales.', 'Capítulos de libro', 'Pensamiento variacional', 'Docentes', '2024', 'PDF', 6, '{"src":"/biblioteca/portadas/27-rubrica-evaluar-desarrollo-pensamiento.webp","alt":"Portada de «Rúbrica para evaluar el desarrollo del pensamiento y lenguaje variacional»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/SOMIDEM/S3/2024/01-26', 'Editorial SOMIDEM', '10.24844/somidem/s3/2024/01-26', 'Cabrera Chim, L. M. (2024). Rúbrica para evaluar el desarrollo del pensamiento y lenguaje variacional. Perspectivas actuales de la Educación Matemática, 243–248. https://doi.org/10.24844/somidem/s3/2024/01-26', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '27 milliseconds'),
  ('4546bd82-c5e1-4fd5-ad30-47f64f6278cc', 'Lingüística Sistémico-Funcional en el estudio del lenguaje matemático. Aportaciones desde el análisis de algunos textos algebraicos y del cálculo', NULL, 'Muestra qué aporta la Lingüística Sistémico-Funcional al estudio del lenguaje matemático a partir de tres investigaciones sobre discursos algebraicos: traducciones de textos originales de la historia del álgebra y producciones de estudiantes al resolver problemas del álgebra de Viète y Descartes.', 'Artículos', 'Álgebra y lenguaje matemático', 'Investigadoras e investigadores', '2024-08', 'PDF', 24, '{"src":"/biblioteca/portadas/31-linguistica-sistemico-funcional-estudio.webp","alt":"Portada de «Lingüística Sistémico-Funcional en el estudio del lenguaje matemático. Aportaciones desde el análisis de algunos textos algebraicos y del cálculo»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://archivo.revistas.ucr.ac.cr/index.php/cifem/article/view/59706', 'Cuadernos de Investigación y Formación en Educación Matemática', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '28 milliseconds'),
  ('31d5d001-a578-42ca-8283-80183ea6b5ef', 'La periodicidad: significados desde su uso en la huerta escolar para la matemática escolar', NULL, 'Ante la poca relación entre la matemática escolar y la de fuera de la escuela, propone descentrar la mirada del objeto matemático hacia las prácticas de las que emerge. Toma el caso de la propiedad periódica y analiza su uso en la huerta escolar como contexto de significación.', 'Artículos', 'Pensamiento variacional', 'Investigadoras e investigadores', '2024', 'PDF', NULL, '{"src":"/biblioteca/portadas/37-periodicidad-significados-desde-uso.webp","alt":"Portada de «La periodicidad: significados desde su uso en la huerta escolar para la matemática escolar»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.54541/reviem.v4i1.101', 'REVIEM', '10.54541/reviem.v4i1.101', 'Balda Álvarez, P. A. y Buendía Abalos, G. (2024). La periodicidad: significados desde su uso en la huerta escolar para la matemática escolar. Revista Venezolana de Investigación en Educación Matemática, 4(1), 1–24. https://doi.org/10.54541/reviem.v4i1.101', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '29 milliseconds'),
  ('d57d5fdd-05c9-4df1-8021-9937bb749fa3', 'Las interacciones entre y con profesores de matemáticas como un recurso para la construcción de conocimiento profesional', NULL, 'Dos experiencias con profesores en activo en las que las interacciones son el recurso principal para construir conocimiento profesional, alrededor del concepto de variable y sus tres usos: qué importancia tienen las interacciones en los espacios de desarrollo profesional y qué ponen los profesores en el centro como información relevante.', 'Capítulos de libro', 'Desarrollo profesional docente', 'Formadoras y formadores', '2024', 'PDF', 6, '{"src":"/biblioteca/portadas/39-interacciones-entre-profesores-matematicas.webp","alt":"Portada de «Las interacciones entre y con profesores de matemáticas como un recurso para la construcción de conocimiento profesional»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/SOMIDEM/S3/2024/01-31', 'Editorial SOMIDEM', '10.24844/somidem/s3/2024/01-31', 'Hernández Sánchez, J. A., Ku-Euan, D. A. y Espino, A. (2024). Las interacciones entre y con profesores de matemáticas como un recurso para la construcción de conocimiento profesional. Perspectivas actuales de la Educación Matemática, 277–282. https://doi.org/10.24844/somidem/s3/2024/01-31', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '30 milliseconds'),
  ('d34e84cc-0530-44a8-ac4b-4d8c1ccb6842', 'Diseño de un curso de formación inicial para profesores que integra la modelación matemática escolar con evaluación de tecnologías', NULL, 'Antecedentes y propuesta para incorporar la modelación matemática a la formación inicial docente: un curso semestral que la trabaja primero como objeto matemático y después como estructura para diseñar situaciones de aprendizaje, integrando la evaluación de tecnologías, en una experiencia de investigación-acción.', 'Artículos', 'Desarrollo profesional docente', 'Formadoras y formadores', '2024', 'PDF', NULL, '{"src":"/biblioteca/portadas/49-diseno-curso-formacion-inicial.webp","alt":"Portada de «Diseño de un curso de formación inicial para profesores que integra la modelación matemática escolar con evaluación de tecnologías»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.61174/recacym.v20i1.215', 'El Cálculo y su Enseñanza', '10.61174/recacym.v20i1.215', 'Pérez Vera, I. E. y Salazar Cortez, P. (2024). Diseño de un curso de formación inicial para profesores que integra la modelación matemática escolar con evaluación de tecnologías. El cálculo y su enseñanza, 20(1), 15–44. https://doi.org/10.61174/recacym.v20i1.215', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '31 milliseconds'),
  ('f7a5d3cd-5c10-4fb9-b50d-3d4e0c4fa8eb', 'Modelación matemática como propuesta de trabajo para superar obstáculos y dificultades en el cálculo escolar. Una experiencia en formación inicial docente', NULL, 'Aborda las dificultades para aprender límite, derivada e integral en secundaria y en la formación docente, y propone la modelación mediada por tecnología como alternativa: cinco fases para diseñar situaciones de aprendizaje desde el enfoque socioepistemológico.', 'Actas de congreso', 'Tecnología y modelación', 'Formadoras y formadores', '2024', 'PDF', NULL, '{"src":"/biblioteca/portadas/50-modelacion-matematica-propuesta-trabajo.webp","alt":"Portada de «Modelación matemática como propuesta de trabajo para superar obstáculos y dificultades en el cálculo escolar. Una experiencia en formación inicial docente»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://alme.org.mx/revista/index.php/alme/article/view/100', 'ALME', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '32 milliseconds'),
  ('b96b56bd-8834-4566-beb1-8fcb1ffb16d5', 'Decision-Making in Situations of Uncertainty as School Mathematical Knowledge', NULL, 'Discute desde la socioepistemología cómo el currículo chileno propone enseñar la toma de decisiones en incertidumbre, un objeto de enseñanza incorporado recientemente en la educación media diferenciada, analizando el programa de estudio y el texto escolar oficial.', 'Artículos', 'Estadística y probabilidad', 'Investigadoras e investigadores', '2024', 'PDF', NULL, '{"src":"/biblioteca/portadas/54-decision-making-situations-uncertainty.webp","alt":"Portada de «Decision-Making in Situations of Uncertainty as School Mathematical Knowledge»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'http://www.periodicos.ulbra.br/index.php/acta/article/view/7705', 'Acta Scientiae', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '33 milliseconds'),
  ('2e14b88e-8d13-4997-a8ca-91a558adee97', 'Dimensiones tecnológicas en tareas de libros de texto de matemáticas', NULL, 'Analiza 189 tareas con tecnología de ocho libros de texto de secundaria y las clasifica según la dimensión tecnológica que promueven (informática, técnica o didáctica). Hay diferencias entre los modelos SEP 2011 y 2017 y entre ejes temáticos, y una tendencia favorable a un uso razonado de la tecnología en las aulas.', 'Artículos', 'Tecnología y modelación', 'Docentes', '2023', 'PDF', 17, '{"src":"/biblioteca/portadas/07-dimensiones-tecnologicas-redie.webp","alt":"Portada de «Dimensiones tecnológicas en tareas de libros de texto de matemáticas»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24320/redie.2023.25.e19.4527', 'REDIE', '10.24320/redie.2023.25.e19.4527', 'Hernández Sánchez, J. A., Padilla Márquez, C. A. E. y Briceño Solís, E. C. (2023). Dimensiones tecnológicas en tareas de libros de texto de matemáticas. Revista Electrónica de Investigación Educativa, 25, 1–17. https://doi.org/10.24320/redie.2023.25.e19.4527', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '34 milliseconds'),
  ('5471e52b-f82a-4bbd-af7d-a156ceeb858a', 'Significados otorgados a las literales por estudiantes de secundaria y universitarios de nuevo ingreso', NULL, 'Explora los significados que estudiantes de secundaria y de nuevo ingreso a ingeniería y a la licenciatura en matemáticas dan a las literales en una tarea: los roles de constante, número general e incógnita según Küchemann, y cómo inciden en los errores al resolver un ítem algebraico planteado desde un contexto geométrico.', 'Artículos', 'Álgebra y lenguaje matemático', 'Investigadoras e investigadores', '2023', 'PDF', NULL, '{"src":"/biblioteca/portadas/38-significados-otorgados-literales-por.webp","alt":"Portada de «Significados otorgados a las literales por estudiantes de secundaria y universitarios de nuevo ingreso»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.33010/ie_rie_rediech.v14i0.1787', 'IE REDIECH', '10.33010/ie_rie_rediech.v14i0.1787', 'Páez Murillo, R. E., Hernández Sánchez, J. A. y Ku-Euan, D. A. (2023). Significados otorgados a las literales por estudiantes de secundaria y universitarios de nuevo ingreso. IE Revista de Investigación Educativa de la REDIECH, 14, e1787. https://doi.org/10.33010/ie_rie_rediech.v14i0.1787', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '35 milliseconds'),
  ('8ecfeba5-dca5-43c6-946c-298e9884fed5', 'Modos de pensar el conjunto Z4 en docentes que enseñan álgebra en los primeros años escolares', NULL, 'Caracteriza modos de pensar el conjunto Z4 en treinta docentes chilenos de primaria en servicio, a partir de un cuestionario y un modelo cognitivo propuesto: muestran más articulación entre los modos sintético-geométrico y analítico-aritmético que con el analítico-estructural, un pensamiento teórico menos privilegiado.', 'Artículos', 'Álgebra y lenguaje matemático', 'Formadoras y formadores', '2023-08', 'PDF', NULL, '{"src":"/biblioteca/portadas/51-modos-pensar-conjunto-z4.webp","alt":"Portada de «Modos de pensar el conjunto Z4 en docentes que enseñan álgebra en los primeros años escolares»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/EM3502.07', 'Educación Matemática', '10.24844/em3502.07', 'Vidal-Szabó, P., Parraguez, M., Bonilla, D. y Campos, S. (2023). Modos de pensar el conjunto Z4 en docentes que enseñan álgebra en los primeros años escolares. Educación Matemática, 35(2), 170–195. https://doi.org/10.24844/em3502.07', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '36 milliseconds'),
  ('83f2a769-d753-4892-bd6e-788b1a670db8', 'Explorando la extensión del modelo MTSK al dominio estadístico: características del aprendizaje desde la taxonomía SOLO', NULL, 'Amplía el modelo de Conocimiento Especializado del Profesor de Matemáticas a la estadística: explora, con la taxonomía SOLO, los conocimientos didácticos y los niveles de comprensión de 192 docentes sobre las dificultades de estudiantes de educación básica para interpretar una tabla de datos.', 'Artículos', 'Estadística y probabilidad', 'Investigadoras e investigadores', '2023', 'PDF', NULL, '{"src":"/biblioteca/portadas/53-explorando-extension-modelo-mtsk.webp","alt":"Portada de «Explorando la extensión del modelo MTSK al dominio estadístico: características del aprendizaje desde la taxonomía SOLO»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.29035/redes.2.1.3', 'Revista de Educación Estadística', '10.29035/redes.2.1.3', 'Vidal-Szabó, P. y Estrella, S. (2023). Explorando la extensión del modelo MTSK al dominio estadístico: características del aprendizaje desde la taxonomía SOLO. Revista de Educación Estadística, 2(1), 1–25. https://doi.org/10.29035/redes.2.1.3', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '37 milliseconds'),
  ('61f6e209-40bc-42f4-b6b8-b18a48830a34', 'Análisis de interpretaciones de gráficas de movimiento y sus implicaciones didácticas. Un estudio de caso', NULL, 'Reanálisis del significado que un estudiante de bachillerato construye sobre gráficas de movimiento con tecnología digital: sus explicaciones revelan usos de las gráficas y, a partir de ellos, se proponen actividades para enseñar gráficas cartesianas.', 'Artículos', 'Pensamiento variacional', 'Docentes', '2022-05', 'PDF', 24, '{"src":"/biblioteca/portadas/12-graficas-de-movimiento.webp","alt":"Portada de «Análisis de interpretaciones de gráficas de movimiento y sus implicaciones didácticas. Un estudio de caso»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.scielo.org.mx/scielo.php?script=sci_arttext&pid=S1665-26732022000200097', 'SciELO', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '38 milliseconds'),
  ('8577d001-b5e0-4539-9fed-8f39d65e905c', 'Aprendizaje de las matemáticas: ¿qué, para qué, para quién?', NULL, 'Una reflexión sobre el aprendizaje de las matemáticas desde el punto de vista de quienes participan en programas de intervención de desarrollo profesional docente: qué problemáticas y qué enfoques del aprendizaje se desarrollaron en las últimas décadas en la Matemática Educativa, y por qué el aprendizaje no se explica desde un solo aspecto.', 'Artículos', 'Desarrollo profesional docente', 'Docentes', '2022-11', 'PDF', 17, '{"src":"/biblioteca/portadas/18-aprendizaje-matematicas-que-que.webp","alt":"Portada de «Aprendizaje de las matemáticas: ¿qué, para qué, para quién?»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://propuestaeducativa.flacso.org.ar/wp-content/uploads/2023/04/REVISTA-58-Dossier-pag-21-37.pdf', 'Propuesta Educativa', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '39 milliseconds'),
  ('c62342e8-7d0a-471f-bdaf-5dc3273de184', 'Nunca recordé la tabla del 7, pero siento que soy buena en matemáticas', NULL, 'Una nota para repensar la dicotomía entre quienes «saben» y quienes «no saben» matemáticas: más que memorizar tablas, importa desarrollar el pensamiento matemático funcional, comparar, estimar, agrupar y entender por qué 7 × 8 da 56.', 'Divulgación', 'Divulgación científica', 'Docentes', '2022', 'Web', NULL, '{"src":"/biblioteca/portadas/20-nunca-recorde-tabla-7.webp","alt":"Portada de «Nunca recordé la tabla del 7, pero siento que soy buena en matemáticas»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.robertorocca.org/es/articulos/2022/nunca-recorde-la-tabla-del-7-pero-siento-que-soy-buena-en-matematicas', 'Roberto Rocca', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '40 milliseconds'),
  ('d4c3ba3a-5686-4a09-ab23-a485d6d39077', 'Análisis de la resolución de un problema de cinemática mediante el mapa conceptual híbrido', NULL, 'Interpreta el mapa conceptual híbrido a partir del enfoque ontosemiótico adaptado a la física escolar y lo usa, en un estudio de caso, para analizar cómo una profesora y dos estudiantes universitarios resuelven un problema de movimiento parabólico: la organización y conexión de los objetos fisicomatemáticos en juego.', 'Artículos', 'Tecnología y modelación', 'Investigadoras e investigadores', '2021', 'PDF', 20, '{"src":"/biblioteca/portadas/26-analisis-resolucion-problema-cinematica.webp","alt":"Portada de «Análisis de la resolución de un problema de cinemática mediante el mapa conceptual híbrido»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.5565/rev/ensciencias.3106', 'Enseñanza de las Ciencias', '10.5565/rev/ensciencias.3106', 'Moreno Martínez, N., Hernández Zavala, L. E. y Briceño Solís, E. C. (2021). Análisis de la resolución de un problema de cinemática mediante el mapa conceptual híbrido. Enseñanza de las Ciencias. Revista de investigación y experiencias didácticas, 39(3), 157–176. https://doi.org/10.5565/rev/ensciencias.3106', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '41 milliseconds'),
  ('071d4634-8c1b-4423-81be-51561480638d', 'Experiencias de aprendizaje y reconceptualización geométrica: una propuesta para la reorganización de la práctica docente', NULL, 'Propuesta para reorganizar la práctica docente a partir de experiencias de aprendizaje que reconceptualizan la geometría escolar. Capítulo del libro Prospecção de Problemas e Soluções nas Ciências Matemáticas 3 (Atena Editora, Brasil).', 'Capítulos de libro', 'Geometría', 'Docentes', '2020', 'PDF', 33, '{"src":"/biblioteca/portadas/05-reconceptualizacion-geometrica.webp","alt":"Portada de «Experiencias de aprendizaje y reconceptualización geométrica: una propuesta para la reorganización de la práctica docente»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://atenaeditora.com.br/catalogo/ebook/prospeccao-de-problemas-e-solucoes-nas-ciencias-matematicas-3', 'Atena Editora', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '42 milliseconds'),
  ('59e331f3-d253-4038-9426-da28217360e6', 'Conceptual and procedural learning in pre-service mathematics teachers during a conversation', NULL, 'Estudio con doce futuros docentes y su instructor sobre el paso del aprendizaje procedimental al conceptual en una tarea geométrica, desde un enfoque de aprendizaje conversacional: al confrontar procedimientos y comprensiones en la conversación, pasan de usar la fórmula del área a darle significado a las figuras por las relaciones entre sus dimensiones.', 'Actas de congreso', 'Geometría', 'Formadoras y formadores', '2020', 'PDF', 9, '{"src":"/biblioteca/portadas/06-conceptual-procedural-pme-na.webp","alt":"Portada de «Conceptual and procedural learning in pre-service mathematics teachers during a conversation»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://eric.ed.gov/?id=ED629884', 'ERIC', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '43 milliseconds'),
  ('4ea0b4a5-6468-4630-b5d5-7fdf2f6704de', 'Reflexive Conversation: Approach to the Professional Learning of Pre-service Mathematics Teachers', NULL, 'Estudia cómo la conversación reflexiva lleva a docentes de matemáticas en formación a un aprendizaje colectivo. Once estudiantes y su formador discutieron la solución de una tarea en dos sesiones; el análisis conversacional muestra que un tema tratado de forma libre y abierta transforma el conocimiento individual en conocimiento común.', 'Artículos', 'Desarrollo profesional docente', 'Formadoras y formadores', '2020', 'PDF', NULL, '{"src":"/biblioteca/portadas/21-reflexive-conversation-approach-to.webp","alt":"Portada de «Reflexive Conversation: Approach to the Professional Learning of Pre-service Mathematics Teachers»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.13189/ujer.2020.080516', 'Universal Journal of Educational Research', '10.13189/ujer.2020.080516', 'Aparicio Landa, E., Sosa Moguel, L., Cabañas-Sánchez, G. y Gómez Osalde, K. (2020). Reflexive Conversation: Approach to the Professional Learning of Pre-service Mathematics Teachers. Universal Journal of Educational Research, 8(5), 1797–1809. https://doi.org/10.13189/ujer.2020.080516', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '44 milliseconds'),
  ('e677f12b-4a52-4562-91c0-9e3d6847476a', 'Reconceptualización de la geometría escolar como medio para la profesionalización docente en matemáticas de educación básica', NULL, 'Propuesta de profesionalización docente en matemáticas para educación básica: favorecer contextos de reconceptualización de los saberes escolares y de las prácticas educativas, y estudiar el papel de la reconceptualización geométrica en la conciencia docente sobre los alcances y límites de su práctica para el pensamiento geométrico espacial.', 'Actas de congreso', 'Geometría', 'Formadoras y formadores', '2020', 'PDF', NULL, '{"src":"/biblioteca/portadas/22-reconceptualizacion-geometria-escolar-medio.webp","alt":"Portada de «Reconceptualización de la geometría escolar como medio para la profesionalización docente en matemáticas de educación básica»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://conferencia.ciaem-redumate.org/index.php/xvciaem/xv/paper/view/331', 'CIAEM', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '45 milliseconds'),
  ('7de4adf0-675d-4719-9abe-8606e214b636', 'Matemática Educativa, transversalidad y COVID-19', 'Ricardo Cantoral Uriza, Diana Wendolyne Ríos Jarquín, Daniela Reyes-Gasperini y diez autoras y autores más', 'Relaciona nociones de la Matemática Educativa con la transversalidad de los saberes matemáticos en la pandemia por coronavirus: el papel del pensamiento matemático para comprender la situación y las medidas preventivas, y la noción de aula extendida.', 'Artículos', 'Desarrollo profesional docente', 'Docentes', '2020', 'PDF', NULL, '{"src":"/biblioteca/portadas/40-matematica-educativa-transversalidad-covid.webp","alt":"Portada de «Matemática Educativa, transversalidad y COVID-19»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.12802/relime.2020.39', 'RELIME', '10.12802/relime.2020.39', 'Cantoral Uriza, R., Ríos Jarquín, W., Reyes Gasperini, D., Cantoral Uriza, E. A., Barrios Borges, E., Fallas Soto, R., Castillo Bárcenas, D., Cantoral Farfán, E., Flores García, R., Galo Alvarenga, S., Paredes Cancino, C., García Zaragoza, V. y Bonilla Solano, A. (2020). Matemática Educativa, transversalidad y COVID-19. Revista Latinoamericana de Investigación en Matemática Educativa, 23(1). https://doi.org/10.12802/relime.2020.39', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '46 milliseconds'),
  ('5758266f-172e-427b-b6e8-f912fcb92e57', 'Análisis cualitativo de un aprendizaje estadístico temprano con la mirada de los Espacios de Trabajo Matemático orientado por el Ciclo Investigativo', NULL, 'Describe y caracteriza una lección de estadística temprana de análisis exploratorio de datos en cuarto grado, con las representaciones de datos producidas por tres estudiantes de 9 y 10 años, analizadas según el ciclo investigativo y las génesis de los Espacios de Trabajo Matemático.', 'Artículos', 'Estadística y probabilidad', 'Investigadoras e investigadores', '2020-08', 'PDF', NULL, '{"src":"/biblioteca/portadas/52-analisis-cualitativo-aprendizaje-estadistico.webp","alt":"Portada de «Análisis cualitativo de un aprendizaje estadístico temprano con la mirada de los Espacios de Trabajo Matemático orientado por el Ciclo Investigativo»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/EM3202.09', 'Educación Matemática', '10.24844/em3202.09', 'Vidal-Szabó, P., Kuzniak, A., Estrella, S. y Montoya, E. (2020). Análisis cualitativo de un aprendizaje estadístico temprano con la mirada de los Espacios de Trabajo Matemático orientado por el Ciclo Investigativo. Educación Matemática, 32(2), 217–246. https://doi.org/10.24844/em3202.09', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '47 milliseconds'),
  ('7e68b917-4b7f-4894-b189-4f459c89e723', '¿Qué podemos aprender de nuestros estudiantes? Reflexiones en torno al uso de las gráficas', NULL, 'Analiza los usos de las gráficas que surgen cuando estudiantes de bachillerato de 15 a 17 años enfrentan una situación de modelación del movimiento con apoyo de tecnología: lo que el discurso escolar tomaría por errores conceptuales se lee como formas culturales de saber, con la variación y el comportamiento con tendencia en el centro de la resignificación.', 'Artículos', 'Tecnología y modelación', 'Docentes', '2019-08', 'PDF', 29, '{"src":"/biblioteca/portadas/25-que-podemos-aprender-nuestros.webp","alt":"Portada de «¿Qué podemos aprender de nuestros estudiantes? Reflexiones en torno al uso de las gráficas»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.24844/EM3102.09', 'Educación Matemática', '10.24844/em3102.09', 'Zaldívar Rojas, J. D. y Briceño Solís, E. C. (2019). ¿Qué podemos aprender de nuestros estudiantes? Reflexiones en torno al uso de las gráficas. Educación Matemática, 31(2), 212–240. https://doi.org/10.24844/em3102.09', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '48 milliseconds'),
  ('77e32742-f657-4908-8491-ea501f0b05f0', 'Plan Nacional Aprender Matemática, colección para el profesor', 'Coordinación de Daniela Reyes-Gasperini, con Luis Manuel Cabrera Chim y Diana Wendolyne Ríos Jarquín', 'La colección de cuadernillos del Plan Nacional Aprender Matemática del Ministerio de Educación de Argentina, con propuestas para el aula organizadas por concepto (inferir, medir, aproximar, comparar, equivaler, predecir, visualizar), para descargar gratis. Coordinada por Daniela Reyes-Gasperini, con Luis Cabrera Chim y Wendolyne Ríos Jarquín entre sus autoras y autores.', 'Materiales', 'Desarrollo profesional docente', 'Docentes', '2019', 'Web', NULL, '{"src":"/biblioteca/portadas/28-plan-nacional-aprender-matematica.webp","alt":"Portada de «Plan Nacional Aprender Matemática, colección para el profesor»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.argentina.gob.ar/noticias/plan-nacional-aprender-matematica-materiales-gratis-para-descargar', 'Argentina.gob.ar', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '49 milliseconds'),
  ('07ae0b6b-a6a5-49c4-8a63-6ecc68c6137a', 'El uso del conocimiento matemático en las comunidades de ingenieros. Del objeto a la funcionalidad matemática', NULL, 'Desde la Teoría Socioepistemológica, estudia el uso del conocimiento matemático que emerge en comunidades de ingenieros para tender un diálogo entre la matemática escolar y el quehacer de la ingeniería: tres ejemplos que cuestionan el saber escolar y destacan usos como la simbiosis entre predicción y simulación y la modelación de la acumulación y la optimización.', 'Artículos', 'Tecnología y modelación', 'Investigadoras e investigadores', '2018-12', 'PDF', 25, '{"src":"/biblioteca/portadas/23-uso-conocimiento-matematico-comunidades.webp","alt":"Portada de «El uso del conocimiento matemático en las comunidades de ingenieros. Del objeto a la funcionalidad matemática»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.1590/1980-4415v32n62a23', 'Bolema', '10.1590/1980-4415v32n62a23', 'Mendoza-Higuera, E. J., Cordero, F., Solís, M. y Gómez Osalde, K. (2018). El uso del conocimiento matemático en las comunidades de ingenieros. Del objeto a la funcionalidad matemática. Bolema: Boletim de Educação Matemática, 32(62), 1219–1243. https://doi.org/10.1590/1980-4415v32n62a23', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '50 milliseconds'),
  ('8de04245-2304-4677-9553-843773e5496b', 'Reconceptualización del saber matemático en educación básica', NULL, 'Un libro para reflexionar sobre la naturaleza conceptual, procedimental y estructural de los saberes matemáticos de educación básica y ampliar sus significados: números y cantidades, geometría, probabilidad y estadística, pensado como guía de autorreflexión para la práctica docente.', 'Libros', 'Desarrollo profesional docente', 'Docentes', '2018', 'Web', NULL, '{"src":"/biblioteca/portadas/24-reconceptualizacion-saber-matematico-educacion.webp","alt":"Portada de «Reconceptualización del saber matemático en educación básica»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://libreria.uady.mx/products/reconceptualizacion-del-saber-matematico-en-educacion-basica', 'Librería UADY', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '51 milliseconds'),
  ('73c41ab3-4053-4ec5-908e-c340aee1d9fb', 'La modelación matemática en los procesos de formación inicial y continua de docentes', NULL, 'Propone la modelación matemática como eje de la formación inicial y continua: docentes que viven y resuelven, en el rol de estudiantes, una situación de contexto biológico cuyas tareas recorren las etapas del proceso de modelación, con una herramienta tecnológica que facilita pasar del problema al modelo.', 'Artículos', 'Tecnología y modelación', 'Formadoras y formadores', '2017-10', 'PDF', 26, '{"src":"/biblioteca/portadas/11-modelacion-formacion-docentes.webp","alt":"Portada de «La modelación matemática en los procesos de formación inicial y continua de docentes»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.redalyc.org/journal/5216/521653370007/html/', 'Redalyc', NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '52 milliseconds'),
  ('c9144f58-8df0-4bfb-bd00-370457842df6', 'Empoderamiento docente y Socioepistemología. Un estudio sobre la transformación educativa en Matemáticas', NULL, 'El libro que le da nombre a ED: cómo el constructo de empoderamiento, tomado de la psicología social, entra en la Matemática Educativa desde la línea del desarrollo profesional docente. El cambio de relación con el conocimiento matemático, a través de la problematización de la matemática escolar, favorece autonomía y liderazgo para transformarse y transformar el entorno.', 'Libros', 'Desarrollo profesional docente', 'Formadoras y formadores', '2016-10', 'PDF', 216, '{"src":"/biblioteca/portadas/04-libro-empoderamiento-docente.webp","alt":"Portada de «Empoderamiento docente y Socioepistemología. Un estudio sobre la transformación educativa en Matemáticas»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://books.google.com/books?vid=ISBN9788416919437', 'Google Books', NULL, NULL, 2, 'El libro', 'La investigación que le da nombre a ED.', 'Publicado por Gedisa en 2016, recoge el estudio doctoral sobre el empoderamiento docente desde la Socioepistemología: por qué problematizar la matemática escolar cambia la relación con el saber y abre autonomía y liderazgo en el profesorado.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '53 milliseconds'),
  ('4fbeac14-2250-47ec-adcf-6d44399c2426', 'Oaxaca: una transformación colectiva con impacto social y educativo', NULL, 'Muestra cómo, en condiciones adversas, el profesorado oaxaqueño asume una actitud de transformación. Caracteriza el dispositivo de la Maestría en Enseñanza de las Matemáticas en la Educación Secundaria en Oaxaca, que potencia las fortalezas docentes sobre la base de la problematización de la matemática escolar, con el seminario sobre lo proporcional como ejemplo.', 'Artículos', 'Desarrollo profesional docente', 'Equipos directivos', '2016', 'PDF', 31, '{"src":"/biblioteca/portadas/01-oaxaca-transformacion-colectiva.webp","alt":"Portada de «Oaxaca: una transformación colectiva con impacto social y educativo»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://www.redalyc.org/articulo.oa?id=13250921004', 'Redalyc', NULL, NULL, 3, 'Oaxaca', 'Una transformación colectiva con impacto social.', 'El caso que ED usa para explicar que escalar una política de formación no es replicar un formato: un dispositivo situado que potenció las fortalezas del profesorado oaxaqueño y llegó a sus aulas.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '54 milliseconds'),
  ('5e3cac67-c5c4-414b-a266-e25b54d7202a', 'Empoderamiento docente desde una visión socioepistemológica: una alternativa de intervención para la transformación y la mejora educativa', NULL, 'La tesis doctoral en el Cinvestav, dirigida por Ricardo Cantoral y Gisela Montiel, que fundamenta el empoderamiento docente como alternativa de intervención para la transformación y la mejora educativa: el marco socioepistemológico, el dispositivo de trabajo con docentes y la evidencia del cambio de relación con la matemática escolar.', 'Tesis', 'Desarrollo profesional docente', 'Investigadoras e investigadores', '2016-08', 'PDF', 598, '{"src":"/biblioteca/portadas/03-tesis-empoderamiento-docente.webp","alt":"Portada de «Empoderamiento docente desde una visión socioepistemológica: una alternativa de intervención para la transformación y la mejora educativa»","foco":{"x":0.5,"y":0.5}}'::jsonb, '/biblioteca/reyes-gasperini-2016-tesis-doctoral.pdf', 'PDF', NULL, 'Reyes-Gasperini, D. (2016). Empoderamiento docente desde una visión socioepistemológica: una alternativa de intervención para la transformación y la mejora educativa [Tesis de doctorado, Centro de Investigación y de Estudios Avanzados del IPN]. https://empoderamientodocente.org/biblioteca/reyes-gasperini-2016-tesis-doctoral.pdf', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '55 milliseconds'),
  ('cf6c2e66-f0f6-4758-9cbe-b54987a6f2a9', 'Socioepistemología y empoderamiento: la profesionalización docente desde la problematización del saber matemático', NULL, 'Postula el empoderamiento como el proceso que atiende la profesionalización docente desde una mirada socioepistemológica: problematizar el saber matemático escolar para pasar de una matemática de objetos abstractos a una construida desde las prácticas sociales, con la democratización del aprendizaje como horizonte.', 'Artículos', 'Desarrollo profesional docente', 'Investigadoras e investigadores', '2014', 'PDF', 23, '{"src":"/biblioteca/portadas/17-socioepistemologia-empoderamiento-profesionalizacion-docente.webp","alt":"Portada de «Socioepistemología y empoderamiento: la profesionalización docente desde la problematización del saber matemático»","foco":{"x":0.5,"y":0.5}}'::jsonb, 'https://doi.org/10.1590/1980-4415v28n48a18', 'Bolema', '10.1590/1980-4415v28n48a18', 'Reyes-Gasperini, D. y Cantoral, R. (2014). Socioepistemología y empoderamiento: la profesionalización docente desde la problematización del saber matemático. Bolema: Boletim de Educação Matemática, 28(48), 360–382. https://doi.org/10.1590/1980-4415v28n48a18', NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP + interval '56 milliseconds');
